insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('maxtrax-mkii','Deano_LC300','LandCruiser 300',5,'Buried to the diffs at Stockton, two boards and drove straight out. Worth every cent.');
insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('maxtrax-mkii','TritonTom','Triton MR',5,'Copies snap. These don''t. Get the mounting pins too.');
insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('ome-bp51-lc300','SaharaSteve','LandCruiser 300 Sahara',5,'Fully loaded with a van on the back and it soaks up corrugations. Set and forget.');
insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('arb-summit-bar-ranger','WildtrakWes','Ranger Wildtrak',5,'Bolted straight up, sensors all work. Looks factory.');
insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('safari-snorkel-lc300','VXVince','LandCruiser 300 VX',4,'Fitment took patience around the guard but the template is accurate.');
insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('stedi-st3303-40','NightRunner','Patrol Y62',5,'Turns the Hume into daylight. Roos have nowhere to hide.');
insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('mickeyt-baja-boss-at','PradoPete','Prado 150',5,'Quiet on the highway for an A/T, chews up fire trails.');
insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('rhinorack-pioneer-platform','EverestEmma','Ford Everest',4,'Solid but heavy — get a mate to help lift it up.');
