insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('ironman-bashplate-dmax','DmaxDan','Isuzu D-Max',5,'Took a rock strike at Yalwal that would''ve holed the sump. Not a mark inside.');
insert into part_reviews (part_id,user_name,vehicle,stars,body) values ('arb-twin-compressor','BeachBoss','Patrol Y62',5,'Airs the whole convoy back up at the exit. Loud but quick.');
