insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('watagans','Watagans National Park','Central Coast','NSW',-33.03,151.38,'easy','forest',40,4,false,false,'Rainforest gullies and firetrails an hour north of Sydney. The classic first-timer''s day out.',ARRAY['High clearance','Recovery gear (mud after rain)']::text[],'Year-round, sticky after rain') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('stockton','Stockton Beach (Worimi)','Port Stephens','NSW',-32.8,152,'medium','beach',32,5,true,false,'32km of open sand dunes. Air down hard and watch the tide — the big dunes bite the unprepared.',ARRAY['Permit (Worimi)','Air down to ~18psi','Recovery boards','Sand flag']::text[],'Year-round') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('yalwal','Yalwal / Danjera Dam','Shoalhaven','NSW',-34.87,150.42,'extreme','river',18,6,false,true,'One of NSW''s toughest. Rock steps and bog holes that will stop built trucks. Lockers and a lift strongly advised.',ARRAY['Front & rear lockers','2"+ lift','35s+','Winch','Travel in a group']::text[],'Drier months only') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('barrington','Barrington Tops NP','Hunter','NSW',-32.05,151.45,'medium','mountain',55,6,false,false,'High-country plateau — snow gums, alpine cold, deep ruts. Weather turns fast up top.',ARRAY['Warm gear','Traction boards','Full fuel — no services']::text[],'Closed/boggy in wet winter') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('colo','Upper Colo River','Hawkesbury','NSW',-33.4,150.75,'medium','river',22,4,false,true,'Sandy river crossings and shady camps close to Sydney. Level rises quickly after upstream rain.',ARRAY['Snorkel recommended','Check river height','Recovery gear']::text[],'Avoid after heavy rain') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('blacksmiths','Nine Mile / Blacksmiths Beach','Lake Macquarie','NSW',-33.08,151.65,'easy','beach',9,2,true,true,'Relaxed beach run near Newcastle. Rangers patrol — unregistered vehicles get a $220 on-the-spot fine.',ARRAY['Beach permit','Air down','Registered vehicle only']::text[],'Year-round') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('bridle-track','Bridle Track (Bathurst)','Central West','NSW',-33.3,149.55,'easy','mountain',45,3,false,true,'Historic gold-country road carved into the Macquarie River gorge. Scenic, mostly formed dirt.',ARRAY['High clearance','Care on narrow edges']::text[],'Year-round') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('abercrombie','Abercrombie River NP','Central Tablelands','NSW',-34.1,149.55,'medium','river',30,5,false,false,'Steep rocky descents to riverside camps. The climbs out are the real work.',ARRAY['Low range','Good tyres','Recovery gear']::text[],'Drier months') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('yengo','Yengo NP (Wollombi)','Hunter','NSW',-32.95,151.13,'hard','forest',28,6,false,false,'Wilderness ridge trails, washouts and rock ledges. Remote — self-recovery is on you.',ARRAY['Rear locker helpful','Winch or a group','Full recovery kit']::text[],'Drier months') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('old-tele','Old Telegraph Track (Gunshot)','Cape York','QLD',-11.55,142.5,'extreme','river',350,40,false,false,'The pilgrimage. Palm Creek, Gunshot, Nolan''s Brook — deep water crossings that drown trucks every dry season.',ARRAY['Snorkel + water blanket','Travel in convoy','Recovery kit','Spares']::text[],'Dry season (Jun–Oct)') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('french-line','Simpson Desert — French Line','Simpson Desert','SA/NT',-26.3,136.1,'hard','desert',500,60,true,false,'1,100+ parallel dunes east to west. Big Red at the end. Total remote self-reliance.',ARRAY['Desert Parks Pass','Sand flag','EPIRB/sat comms','2x fuel range','Convoy']::text[],'Apr–Oct only (closed summer)') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('big-red','Big Red (Birdsville)','Simpson Desert','QLD',-25.9,139.2,'hard','desert',8,1,false,false,'The 40m monster dune at the desert''s edge. Air right down and commit — momentum is everything.',ARRAY['Air down to ~15psi','Recovery boards','Run-up room']::text[],'Apr–Oct') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('billy-goat','Billy Goat Bluff Track','Victorian High Country','VIC',-37.45,147.1,'hard','mountain',8,2,false,true,'Brutally steep, loose shale climb to Pinnacles lookout. Dry weather only — no room for error.',ARRAY['Low range 1st','Good tyres','Dry conditions only','Solo = risky']::text[],'Summer, dry only') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('kgari','K''gari (Fraser Is) — 75 Mile Beach','K''gari','QLD',-25.25,153.15,'medium','beach',120,8,true,false,'The world''s largest sand island. Beach highway, inland tracks, dingoes and tide-timed driving.',ARRAY['Vehicle + camping permits','Tide chart','Air down','Recovery gear']::text[],'Year-round, tide-dependent') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('googs','Googs Track','Eyre Peninsula','SA',-31.3,134.8,'medium','desert',200,12,false,false,'Remote solo desert crossing — 300+ dunes through the sandhills north of Ceduna. No services.',ARRAY['Sand flag','Extra fuel & water','Sat comms','Self-sufficient']::text[],'Apr–Oct') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('blue-rag','Blue Rag Range Track','Victorian High Country','VIC',-37.1,147.2,'medium','mountain',12,3,false,true,'Knife-edge ridgeline to a trig point with 360° alpine views. The photo everyone wants.',ARRAY['Dry conditions','High clearance','Nerve for the edges']::text[],'Summer (closed in snow)') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
insert into tracks (id,name,region,state,lat,lng,difficulty,type,length_km,hours,permit,dog,blurb,needs,season) values ('wonnangatta','Wonnangatta Valley','Victorian High Country','VIC',-37.1,146.78,'medium','mountain',60,8,false,false,'Remote historic cattle-station valley deep in the high country. River crossings and a long haul in — the reward is one of Victoria''s best campsites.',ARRAY['High clearance','Recovery gear','Fuel for 200km+','Check river levels']::text[],'Nov–Apr (closed winter)') on conflict (id) do update set name=excluded.name,region=excluded.region,state=excluded.state,lat=excluded.lat,lng=excluded.lng,difficulty=excluded.difficulty,type=excluded.type,length_km=excluded.length_km,hours=excluded.hours,permit=excluded.permit,dog=excluded.dog,blurb=excluded.blurb,needs=excluded.needs,season=excluded.season;
